'use client';

import React, { useMemo, useRef, useState, useEffect } from 'react';
import Link from 'next/link';
import { CanvasIsometricGrid } from '@/components/game/CanvasIsometricGrid';
import { OverlayMode } from '@/components/game/types';
import { useGame } from '@/context/GameContext';
import { CITYLIFE_TOOLS, CityLifeTool, calculateCityLifeSnapshot } from '@/lib/citylife';
import { Tool } from '@/types/game';

function MetricCard({ label, value, color }: { label: string; value: number; color: string }) {
  const pct = Math.max(0, Math.min(100, value));
  return (
    <div className="rounded-md border border-white/10 bg-slate-900/85 px-3 py-2 backdrop-blur-sm">
      <div className="mb-1 flex items-center justify-between text-xs text-slate-300">
        <span>{label}</span>
        <span className="font-semibold text-white">{value.toFixed(1)}</span>
      </div>
      <div className="h-1.5 w-full overflow-hidden rounded-full bg-white/10">
        <div className={`h-full rounded-full ${color}`} style={{ width: `${pct}%` }} />
      </div>
    </div>
  );
}

function ToolButton({
  tool,
  selected,
  onSelect,
}: {
  tool: CityLifeTool;
  selected: boolean;
  onSelect: (tool: Tool) => void;
}) {
  return (
    <button
      type="button"
      onClick={() => onSelect(tool.tool)}
